/bin/bash -lc "Rscript - <<'RS'
for (f in list.files('inputs', pattern='\\\\.rds"'$'"', full.names=TRUE)) {
  cat('\\n###', f, '\\n')
  x <- readRDS(f)
  a <- attributes(x)
  cat('attribute names:', paste(base::names(a), collapse=' | '), '\\n')
  for (nm in base::names(a)) {
    z <- a[[nm]]
    cat('attr', nm, 'typeof=', typeof(z), 'is.object=', is.object(z), 'base_len=', tryCatch(base::length(z), error=function(e) NA), '\\n')
    if (nm %in% c('elementMetadata','metadata')) {
      cat('  subattr names:', paste(base::names(attributes(z)), collapse=' | '), '\\n')
      cat('  names:', paste(base::names(z), collapse=' | '), '\\n')
    }
  }
}
RS"

/bin/bash -lc "Rscript - <<'RS'
for (f in list.files('inputs', pattern='\\\\.rds"'$'"', full.names=TRUE)) {
  cat('\\n###', f, '\\n')
  x <- readRDS(f); a <- attributes(x); ld <- a[['listData']]
  cat('listData typeof=', typeof(ld), 'length=', base::length(ld), 'names=', paste(base::names(ld), collapse=' | '), '\\n')
  for (nm in base::names(ld)) {
    z <- ld[[nm]]
    cat('column', nm, 'typeof=', typeof(z), 'class attr=', paste(base::attr(z,'class'), collapse=','), 'base_len=', base::length(z), '\\n')
    print(utils::head(z, 4))
  }
}
RS"

/bin/bash -lc "Rscript - <<'RS'
for (f in list.files('inputs', pattern='\\\\.rds"'$'"', full.names=TRUE)) {
  cat('\\n###', f, '\\n')
  x <- readRDS(f); a <- attributes(x)
  for (nm in c('metadata','elementMetadata')) {
    z <- a[[nm]]
    cat('ATTR', nm, 'typeof=',typeof(z),'\\n')
    az <- attributes(z)
    cat('attr names:', paste(base::names(az), collapse=' | '), '\\n')
    if ("'!is.null(az[['"'listData']])) {
      ld <- az[['listData']]
      cat('listData names:', paste(base::names(ld), collapse=' | '), '\\n')
      for (cn in base::names(ld)) {
        q <- ld[[cn]]
        cat(' ',cn, 'type',typeof(q),'len',base::length(q),'\\n')
        if (base::length(q) <= 20) print(q) else print(utils::head(q,3))
      }
    }
  }
}
RS"
